-- Ligue des Nations Concacaf : quarts de finale (Ligue A) et play-in (Ligue A 5e/6e contre Ligue C).
-- Hors classement des groupes (cf. StandingsService). Terrain neutre : Haiti a Miami, Saint-Martin a
-- Basseterre (Saint-Kitts), Montserrat a Santiago (Rep. dominicaine).
INSERT INTO match (competition_id, round_label, date, time, team1_id, team2_id, neutral, status) SELECT (SELECT id FROM competition WHERE code = 'CONCACAF_NL_2627' AND season = 2027), 'Quarts de finale - Aller', DATE '2026-11-13', TIME '01:00', (SELECT id FROM team WHERE name = 'Curacao'), (SELECT id FROM team WHERE name = 'Panama'), FALSE, 'SCHEDULED' WHERE NOT EXISTS (SELECT 1 FROM match WHERE competition_id = (SELECT id FROM competition WHERE code = 'CONCACAF_NL_2627' AND season = 2027) AND team1_id = (SELECT id FROM team WHERE name = 'Curacao') AND team2_id = (SELECT id FROM team WHERE name = 'Panama') AND round_label !~ '^J[0-9]+$'); -- source : 2026-11-12 19:00 officiel (20:00 local), Ergilio Hato Stadium, Willemstad
